<template><section class="workbench"><div class="head"><div><span class="eyebrow">PHM WORKBENCH / {{route.name||'MODULE'}}</span><h2>{{title}}</h2><p>{{description}}</p></div><el-tag type="success">演示算法已启用</el-tag></div><el-alert title="当前使用内置演示算法，提交仿真数据后会立即计算并显示结果。" type="info" :closable="false" show-icon/><div class="grid"><el-card shadow="never"><template #header><b>数据源</b></template><el-form label-position="top"><el-form-item label="数据来源"><el-radio-group v-model="form.source"><el-radio-button label="dataset">仿真数据集</el-radio-button><el-radio-button label="upload">上传文件</el-radio-button><el-radio-button label="history">历史记录</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="form.source==='dataset'" label="场景"><el-select v-model="form.category" placeholder="选择仿真场景" style="width:100%"><el-option v-for="x in categories" :key="x.key" :label="x.name" :value="x.key"/></el-select></el-form-item><el-form-item label="任务备注"><el-input v-model="form.note" type="textarea" :rows="3"/></el-form-item><el-button type="primary" :loading="submitting" @click="submit">提交并运行分析</el-button></el-form></el-card><el-card shadow="never"><template #header><b>算法结果</b></template><el-empty v-if="!result" description="提交数据后显示算法结果"/><div v-else><el-tag type="success">已完成</el-tag><h3>{{result.name}}</h3><el-descriptions :column="2" border><el-descriptions-item label="样本数">{{result.sampleCount}}</el-descriptions-item><el-descriptions-item label="健康评分">{{result.score}}</el-descriptions-item><el-descriptions-item label="异常点数">{{result.anomalies}}</el-descriptions-item><el-descriptions-item label="评估结论">{{result.conclusion}}</el-descriptions-item></el-descriptions><div class="chart"><i v-for="(v,i) in result.series" :key="i" class="bar" :style="{height:`${v*100}%`}"/></div></div></el-card></div><el-card shadow="never" class="features"><template #header><b>模块能力</b></template><el-tag v-for="item in features" :key="item" effect="plain">{{item}}</el-tag></el-card></section></template>
<script setup>import{ref,computed,onMounted}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';const route=useRoute(),title=computed(()=>route.meta.title||'PHM功能模块'),description=computed(()=>route.meta.description||'配置数据源并运行演示算法。'),features=computed(()=>route.meta.features||[]),categories=ref([{key:'baseline',name:'正常基线'},{key:'degraded',name:'退化工况'}]),result=ref(null),submitting=ref(false),form=ref({source:'dataset',category:'baseline',note:''});async function submit(){submitting.value=true;await new Promise(r=>setTimeout(r,250));const d=form.value.category==='degraded',series=Array.from({length:12},(_,i)=>Math.max(.2,(d?.96-i*.035:.96-i*.008)));const anomalies=series.filter(v=>v<.75).length;result.value={name:title.value,sampleCount:120,score:Number((series.reduce((a,b)=>a+b,0)/12).toFixed(3)),anomalies,conclusion:anomalies?'检测到退化趋势':'状态正常',series};localStorage.setItem('phm-result-'+route.path,JSON.stringify(result.value));submitting.value=false;ElMessage.success('分析完成，结果已生成')}onMounted(()=>{const x=localStorage.getItem('phm-result-'+route.path);if(x)result.value=JSON.parse(x)})</script>
<style scoped>.workbench{padding:24px;max-width:1200px}.head{display:flex;justify-content:space-between}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.features{margin-top:18px}.features .el-tag{margin-right:8px}.chart{height:130px;display:flex;align-items:flex-end;gap:6px;margin-top:20px}.bar{flex:1;background:#2389ee;border-radius:3px 3px 0 0}.eyebrow{color:#1677ff;font-size:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style>
